-- ==============================================================================
-- FMCG+ Retail POS & Customer Khata - PostgreSQL Normalized Schema & Master Catalog
-- Target Database: fmcg_pos
-- Features: Canonical 3NF Catalog (623 Items) with UUIDs, Zero-Seed Blank Slate Dokan Inventory
-- ==============================================================================

-- 0. Clean & Reset Existing Schema (Idempotent 3NF Initialization)
DROP VIEW IF EXISTS products CASCADE;
DROP TABLE IF EXISTS stock_movements CASCADE;
DROP TABLE IF EXISTS stock_adjustments CASCADE;
DROP TABLE IF EXISTS khata_entries CASCADE;
DROP TABLE IF EXISTS transaction_items CASCADE;
DROP TABLE IF EXISTS transactions CASCADE;
DROP TABLE IF EXISTS refresh_tokens CASCADE;
DROP TABLE IF EXISTS store_members CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS customers CASCADE;
DROP TABLE IF EXISTS store_inventory CASCADE;
DROP TABLE IF EXISTS stores CASCADE;
DROP TABLE IF EXISTS master_products CASCADE;
DROP TABLE IF EXISTS brands CASCADE;
DROP TABLE IF EXISTS manufacturers CASCADE;
DROP TABLE IF EXISTS subcategories CASCADE;
DROP TABLE IF EXISTS categories CASCADE;

-- 1. Master FMCG Catalog Tables (Global Canonical Catalog)
CREATE TABLE IF NOT EXISTS categories (
    id VARCHAR(36) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    name_bn VARCHAR(100) NOT NULL,
    icon VARCHAR(50)
);

CREATE TABLE IF NOT EXISTS subcategories (
    id VARCHAR(36) PRIMARY KEY,
    category_id VARCHAR(36) NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    name_bn VARCHAR(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS manufacturers (
    id VARCHAR(36) PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    country VARCHAR(50) DEFAULT 'Bangladesh'
);

CREATE TABLE IF NOT EXISTS brands (
    id VARCHAR(36) PRIMARY KEY,
    manufacturer_id VARCHAR(36) REFERENCES manufacturers(id) ON DELETE SET NULL,
    name VARCHAR(150) NOT NULL
);

CREATE TABLE IF NOT EXISTS master_products (
    id VARCHAR(36) PRIMARY KEY,
    barcode VARCHAR(50) UNIQUE NOT NULL,
    product_name VARCHAR(255) NOT NULL,
    product_name_bn VARCHAR(255),
    brand_id VARCHAR(36) REFERENCES brands(id),
    category_id VARCHAR(36) REFERENCES categories(id),
    subcategory_id VARCHAR(36) REFERENCES subcategories(id),
    pack_size VARCHAR(50),
    unit VARCHAR(20) NOT NULL,
    suggested_mrp NUMERIC(10,2),
    suggested_cost NUMERIC(10,2),
    sku VARCHAR(50),
    image_url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_master_barcode ON master_products(barcode);
CREATE INDEX IF NOT EXISTS idx_master_name ON master_products(product_name);
CREATE INDEX IF NOT EXISTS idx_master_brand ON master_products(brand_id);
CREATE INDEX IF NOT EXISTS idx_master_category ON master_products(category_id);

-- 2. User Authentication & Store Tenancy Layer
CREATE TABLE IF NOT EXISTS users (
    id VARCHAR(36) PRIMARY KEY,
    phone VARCHAR(50) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    name_bn VARCHAR(255),
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(50) NOT NULL DEFAULT 'customer',
    is_active BOOLEAN DEFAULT TRUE,
    phone_verified BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_users_phone ON users(phone);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);

-- Store Operational Layer (Multi-tenant Dokan Shelf Inventory)
CREATE TABLE IF NOT EXISTS stores (
    id VARCHAR(36) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    owner_name VARCHAR(150),
    owner_phone VARCHAR(50) NOT NULL,
    address TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS store_members (
    id VARCHAR(36) PRIMARY KEY,
    store_id VARCHAR(36) NOT NULL REFERENCES stores(id) ON DELETE CASCADE,
    user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    member_role VARCHAR(50) NOT NULL DEFAULT 'staff',
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT uq_store_member UNIQUE(store_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_store_members_user ON store_members(user_id);
CREATE INDEX IF NOT EXISTS idx_store_members_store ON store_members(store_id);

CREATE TABLE IF NOT EXISTS refresh_tokens (
    id VARCHAR(36) PRIMARY KEY,
    user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash VARCHAR(64) NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    is_revoked BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_refresh_tokens_hash ON refresh_tokens(token_hash);
CREATE INDEX IF NOT EXISTS idx_refresh_tokens_user ON refresh_tokens(user_id);

CREATE TABLE IF NOT EXISTS store_inventory (
    id VARCHAR(36) PRIMARY KEY,
    store_id VARCHAR(36) NOT NULL REFERENCES stores(id) ON DELETE CASCADE,
    master_product_id VARCHAR(36) REFERENCES master_products(id) ON DELETE SET NULL,
    barcode VARCHAR(50) NOT NULL,
    custom_name VARCHAR(255) NOT NULL,
    custom_name_bn VARCHAR(255),
    cost_price NUMERIC(10,2) NOT NULL,
    selling_price NUMERIC(10,2) NOT NULL,
    current_stock INTEGER NOT NULL DEFAULT 0,
    min_threshold INTEGER NOT NULL DEFAULT 5,
    shelf_location VARCHAR(100),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT uq_store_barcode UNIQUE(store_id, barcode)
);

CREATE INDEX IF NOT EXISTS idx_inventory_store_barcode ON store_inventory(store_id, barcode);
CREATE INDEX IF NOT EXISTS idx_inventory_store_name ON store_inventory(store_id, custom_name);
CREATE INDEX IF NOT EXISTS idx_inventory_store_stock ON store_inventory(store_id, current_stock);

-- 3. Customers & Double-Entry Khata Ledger
CREATE TABLE IF NOT EXISTS customers (
    id VARCHAR(36) PRIMARY KEY,
    store_id VARCHAR(36) NOT NULL REFERENCES stores(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    name_bn VARCHAR(255),
    phone VARCHAR(50) NOT NULL,
    address TEXT,
    credit_limit NUMERIC(10,2) DEFAULT 5000.0,
    current_due NUMERIC(10,2) DEFAULT 0.0,
    lifetime_purchases NUMERIC(10,2) DEFAULT 0.0,
    status VARCHAR(50) DEFAULT 'clear',
    status_label VARCHAR(100) DEFAULT 'Zero Balance',
    promise_date VARCHAR(50),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT uq_store_customer_phone UNIQUE(store_id, phone)
);

CREATE INDEX IF NOT EXISTS idx_customers_store ON customers(store_id);
CREATE INDEX IF NOT EXISTS idx_customers_phone ON customers(phone);

CREATE TABLE IF NOT EXISTS transactions (
    id VARCHAR(36) PRIMARY KEY,
    store_id VARCHAR(36) NOT NULL REFERENCES stores(id) ON DELETE CASCADE,
    order_number VARCHAR(50) NOT NULL,
    customer_id VARCHAR(36) REFERENCES customers(id),
    customer_name VARCHAR(255),
    items JSONB NOT NULL,
    subtotal NUMERIC(10,2) NOT NULL,
    discount NUMERIC(10,2) DEFAULT 0.0,
    total NUMERIC(10,2) NOT NULL,
    paid_amount NUMERIC(10,2) NOT NULL,
    remaining_due NUMERIC(10,2) DEFAULT 0.0,
    payment_method VARCHAR(50) NOT NULL,
    cashier_name VARCHAR(100),
    counter VARCHAR(50),
    auth_code VARCHAR(100),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_trx_store ON transactions(store_id);
CREATE INDEX IF NOT EXISTS idx_trx_order ON transactions(order_number);
CREATE INDEX IF NOT EXISTS idx_trx_customer ON transactions(customer_id);
CREATE INDEX IF NOT EXISTS idx_trx_created ON transactions(created_at);

CREATE TABLE IF NOT EXISTS transaction_items (
    id VARCHAR(36) PRIMARY KEY,
    transaction_id VARCHAR(36) NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
    store_inventory_id VARCHAR(36) REFERENCES store_inventory(id),
    barcode VARCHAR(50) NOT NULL,
    product_name VARCHAR(255) NOT NULL,
    quantity INTEGER NOT NULL,
    unit_price NUMERIC(10,2) NOT NULL,
    cost_price NUMERIC(10,2) NOT NULL,
    subtotal NUMERIC(10,2) NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_trx_items_trx ON transaction_items(transaction_id);

CREATE TABLE IF NOT EXISTS khata_entries (
    id VARCHAR(36) PRIMARY KEY,
    store_id VARCHAR(36) NOT NULL REFERENCES stores(id) ON DELETE CASCADE,
    customer_id VARCHAR(36) NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
    transaction_id VARCHAR(36),
    type VARCHAR(50) NOT NULL,
    label VARCHAR(150) NOT NULL,
    description TEXT,
    order_total NUMERIC(10,2) DEFAULT 0.0,
    paid_amount NUMERIC(10,2) DEFAULT 0.0,
    credit_change NUMERIC(10,2) NOT NULL,
    running_balance NUMERIC(10,2) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_khata_customer ON khata_entries(customer_id);
CREATE INDEX IF NOT EXISTS idx_khata_store ON khata_entries(store_id);

CREATE TABLE IF NOT EXISTS stock_movements (
    id VARCHAR(36) PRIMARY KEY,
    store_id VARCHAR(36) NOT NULL REFERENCES stores(id) ON DELETE CASCADE,
    store_inventory_id VARCHAR(36) NOT NULL REFERENCES store_inventory(id) ON DELETE CASCADE,
    product_name VARCHAR(255) NOT NULL,
    change_qty INTEGER NOT NULL,
    balance_after INTEGER NOT NULL,
    reason VARCHAR(50) NOT NULL,
    reference_id VARCHAR(100),
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_stock_movements_inv ON stock_movements(store_inventory_id);

CREATE OR REPLACE VIEW products AS
SELECT 
    si.id,
    si.store_id,
    si.custom_name AS name,
    COALESCE(c.name, 'General') AS category,
    COALESCE(b.name, '') AS brand,
    COALESCE(mp.pack_size, '') AS pack_size,
    COALESCE(mp.unit, 'pcs') AS unit,
    si.cost_price,
    si.selling_price,
    si.current_stock AS stock,
    si.min_threshold,
    si.barcode,
    COALESCE(mp.sku, CONCAT('SKU-GEN-', SUBSTRING(si.id, 1, 8))) AS sku,
    mp.image_url,
    si.shelf_location,
    si.is_active,
    si.created_at,
    si.updated_at
FROM store_inventory si
LEFT JOIN master_products mp ON si.master_product_id = mp.id
LEFT JOIN categories c ON mp.category_id = c.id
LEFT JOIN brands b ON mp.brand_id = b.id;

CREATE TABLE IF NOT EXISTS stock_adjustments (
    id VARCHAR(36) PRIMARY KEY,
    product_id VARCHAR(36) NOT NULL,
    product_name VARCHAR(255),
    old_stock INTEGER NOT NULL,
    new_stock INTEGER NOT NULL,
    adjusted_qty INTEGER NOT NULL,
    reason VARCHAR(50) NOT NULL,
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Seed Master Categories
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_bn = EXCLUDED.name_bn, icon = EXCLUDED.icon;

-- 3. Seed Master Subcategories
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_bn = EXCLUDED.name_bn;

-- 4. Seed Manufacturers (83 Entities)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;

-- 5. Seed Brands (161 Brands)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, manufacturer_id = EXCLUDED.manufacturer_id;

-- 6. Seed Canonical Master Products (623 Items with UUIDs)
ON CONFLICT (barcode) DO UPDATE SET
    product_name = EXCLUDED.product_name,
    brand_id = EXCLUDED.brand_id,
    category_id = EXCLUDED.category_id,
    subcategory_id = EXCLUDED.subcategory_id,
    pack_size = EXCLUDED.pack_size,
    unit = EXCLUDED.unit,
    suggested_mrp = EXCLUDED.suggested_mrp,
    suggested_cost = EXCLUDED.suggested_cost,
    sku = EXCLUDED.sku,
    image_url = EXCLUDED.image_url,
    updated_at = NOW();
